content.text:
Brief:
An orchard game played in rounds. Each round the player must catch a set number of falling apples in a basket that slides along the bottom of the screen. Rotten apples fall too, and catching one empties the basket. When the round goal is met a short banner announces the next round, which adds wind that pushes the apples sideways. Missing too many apples ends the game with a clear message and a button to try again.

Plan:
{"gameType":"stage-clear","input":"drag-follow","lang":"en","loop":"Slide the basket to catch the round's target number of good apples while dodging rotten ones and wind; catching a rotten apple empties your basket. Clear rounds to face stronger wind, but missing too many apples ends the game with a retry button.","slug":"orchard-catch","style":"paper-cut","title":"Orchard Catch"}

Game source (line-numbered):
1| <!doctype html>
2| <html lang="en">
3| <head>
4| <meta charset="utf-8">
5| <meta name="viewport" content="width=device-width, initial-scale=1">
6| <title>Orchard Catch</title>
7| <style>
8|   html, body {
9|     margin: 0; padding: 0; width: 100%; height: 100%;
10|     background: #f4ecd8;
11|     overflow: hidden;
12|     touch-action: none;
13|     font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
14|   }
15|   canvas {
16|     display: block;
17|     width: 100vw;
18|     height: 100dvh;
19|   }
20| </style>
21| </head>
22| <body>
23| <canvas id="game"></canvas>
24| <script>
25| // ---- Bridge helper (verbatim) ----
26| const CARTRIDGE = {
27|   send(type, payload = {}) {
28|     window.parent.postMessage(
29|       { source: "cartridge", v: 1, type, payload },
30|       "*",
31|     );
32|   },
33| };
34| </script>
35| <script>
36| (function(){
37|   const canvas = document.getElementById('game');
38|   const ctx = canvas.getContext('2d');
39| 
40|   let DPR = Math.max(1, window.devicePixelRatio || 1);
41|   let W = 0, H = 0;
42| 
43|   function resize() {
44|     W = window.innerWidth;
45|     H = window.innerHeight;
46|     DPR = Math.max(1, window.devicePixelRatio || 1);
47|     canvas.width = Math.floor(W * DPR);
48|     canvas.height = Math.floor(H * DPR);
49|     canvas.style.width = W + 'px';
50|     canvas.style.height = H + 'px';
51|     ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
52|   }
53|   window.addEventListener('resize', resize);
54|   resize();
55| 
56|   // ---- Palette ----
57|   const COL_BG = '#f4ecd8';
58|   const COL_LAYER = '#e07a5f';
59|   const COL_ACCENT = '#3d405b';
60|   const COL_HIGHLIGHT = '#81b29a';
61| 
62|   // seeded jitter helper for paper-cut look
63|   function seededRand(seed) {
64|     let s = seed % 2147483647;
65|     if (s <= 0) s += 2147483646;
66|     return function() {
67|       s = (s * 16807) % 2147483647;
68|       return (s - 1) / 2147483646;
69|     };
70|   }
71|   const jrand = seededRand(1337);
72|   function jitter(v, amt) {
73|     return v + (jrand() - 0.5) * amt * 2;
74|   }
75| 
76|   function roundedRectPath(x, y, w, h, r) {
77|     ctx.beginPath();
78|     ctx.moveTo(x + r, y);
79|     ctx.lineTo(x + w - r, y);
80|     ctx.quadraticCurveTo(x + w, y, x + w, y + r);
81|     ctx.lineTo(x + w, y + h - r);
82|     ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
83|     ctx.lineTo(x + r, y + h);
84|     ctx.quadraticCurveTo(x, y + h, x, y + h - r);
85|     ctx.lineTo(x, y + r);
86|     ctx.quadraticCurveTo(x, y, x + r, y);
87|     ctx.closePath();
88|   }
89| 
90|   // ---- Game state ----
91|   let state = 'title'; // 'title', 'playing', 'stageclear', 'gameover', 'win'
92|   let paused = false;
93| 
94|   let stage = 0;
95|   let score = 0;
96|   let caughtGood = 0;
97|   let missed = 0;
98|   let maxMissed = 5;
99|   let goalCount = 5;
100|   let windStrength = 0;
101|   let stageTimer = 0;
102|   let graceTimer = 0;
103| 
104|   const STAGES = [
105|     { goal: 5, wind: 0, maxMiss: 6, spawnRate: 1.1, fallSpeed: 140, badChance: 0.2 },
106|     { goal: 7, wind: 30, maxMiss: 6, spawnRate: 1.0, fallSpeed: 160, badChance: 0.25 },
107|     { goal: 9, wind: 55, maxMiss: 5, spawnRate: 0.85, fallSpeed: 185, badChance: 0.3 },
108|     { goal: 11, wind: 80, maxMiss: 5, spawnRate: 0.75, fallSpeed: 210, badChance: 0.32 },
109|     { goal: 13, wind: 110, maxMiss: 4, spawnRate: 0.65, fallSpeed: 235, badChance: 0.35 },
110|   ];
111| 
112|   // Basket (drag-follow piece)
113|   const basket = {
114|     x: 0, y: 0, targetX: 0,
115|     w: 110, h: 60,
116|   };
117| 
118|   let held = false;
119| 
120|   let fruits = []; // {x,y,vy,r,bad,wobble}
121|   let spawnAccum = 0;
122|   let particles = []; // simple burst effects
123| 
124|   let messageFlashTimer = 0;
125|   let messageFlashText = '';
126| 
127|   function toCanvas(evt) {
128|     const rect = canvas.getBoundingClientRect();
129|     return {
130|       x: (evt.clientX - rect.left) * (rect.width ? 1 : 1),
131|       y: (evt.clientY - rect.top)
132|     };
133|   }
134| 
135|   canvas.addEventListener('pointerdown', (event) => {
136|     if (state === 'title') {
137|       startGame();
138|       return;
139|     }
140|     if (state === 'gameover' || state === 'win') {
141|       backToTitle();
142|       return;
143|     }
144|     const p = toCanvas(event);
145|     held = true;
146|     basket.targetX = p.x;
147|     try { canvas.setPointerCapture(event.pointerId); } catch(e) {}
148|   });
149|   canvas.addEventListener('pointermove', (event) => {
150|     if (held) {
151|       const p = toCanvas(event);
152|       basket.targetX = p.x;
153|     }
154|   });
155|   function releasePointer() { held = false; }
156|   canvas.addEventListener('pointerup', releasePointer);
157|   canvas.addEventListener('pointercancel', releasePointer);
158| 
159|   function backToTitle() {
160|     state = 'title';
161|     paused = false;
162|     fruits = [];
163|     particles = [];
164|     score = 0;
165|     stage = 0;
166|     caughtGood = 0;
167|     missed = 0;
168|   }
169| 
170|   function startGame() {
171|     score = 0;
172|     CARTRIDGE.send('start');
173|     CARTRIDGE.send('score', { value: score });
174|     enterStage(1);
175|     state = 'playing';
176|   }
177| 
178|   function enterStage(next) {
179|     stage = next;
180|     const cfg = STAGES[Math.min(stage - 1, STAGES.length - 1)];
181|     goalCount = cfg.goal;
182|     windStrength = cfg.wind;
183|     maxMissed = cfg.maxMiss;
184|     caughtGood = 0;
185|     missed = 0;
186|     fruits = [];
187|     spawnAccum = 0;
188|     graceTimer = 2.0; // grace period before threats
189|     basket.x = W / 2;
190|     basket.targetX = W / 2;
191|     CARTRIDGE.send('level', { index: stage });
192|     flashMessage('Stage ' + stage + ': Catch ' + goalCount + ' apples');
193|   }
194| 
195|   function flashMessage(text) {
196|     messageFlashText = text;
197|     messageFlashTimer = 2.2;
198|   }
199| 
200|   function onGoalMet() {
201|     if (stage >= STAGES.length) {
202|       state = 'win';
203|       CARTRIDGE.send('end', { reason: 'win', value: score });
204|     } else {
205|       state = 'stageclear';
206|       stageTimer = 1.4;
207|     }
208|   }
209| 
210|   function onStageFailed() {
211|     state = 'gameover';
212|     CARTRIDGE.send('end', { reason: 'lose', value: score });
213|   }
214| 
215|   function spawnFruit(cfg) {
216|     const r = 20 + jrand() * 6;
217|     const bad = jrand() < cfg.badChance;
218|     fruits.push({
219|       x: r + jrand() * (W - 2 * r),
220|       y: -r - 10,
221|       vy: cfg.fallSpeed * (0.85 + jrand() * 0.3),
222|       r: r,
223|       bad: bad,
224|       wobble: jrand() * Math.PI * 2,
225|       seed: jrand() * 1000
226|     });
227|   }
228| 
229|   function spawnBurst(x, y, color) {
230|     for (let i = 0; i < 8; i++) {
231|       particles.push({
232|         x, y,
233|         vx: (jrand() - 0.5) * 160,
234|         vy: (jrand() - 0.5) * 160 - 60,
235|         life: 0.5 + jrand() * 0.3,
236|         color
237|       });
238|     }
239|   }
240| 
241|   let lastTime = performance.now();
242|   function loop(now) {
243|     let dt = (now - lastTime) / 1000;
244|     if (dt > 0.05) dt = 0.05;
245|     lastTime = now;
246| 
247|     if (!paused) update(dt);
248|     render();
249| 
250|     requestAnimationFrame(loop);
251|   }
252| 
253|   function update(dt) {
254|     // ease basket toward target
255|     const ease = 0.18;
256|     basket.x += (basket.targetX - basket.x) * Math.min(1, ease * (dt * 60));
257|     basket.x = Math.max(basket.w / 2, Math.min(W - basket.w / 2, basket.x));
258| 
259|     if (messageFlashTimer > 0) messageFlashTimer -= dt;
260| 
261|     if (state === 'stageclear') {
262|       stageTimer -= dt;
263|       if (stageTimer <= 0) enterStage(stage + 1);
264|       return;
265|     }
266| 
267|     if (state !== 'playing') return;
268| 
269|     if (graceTimer > 0) graceTimer -= dt;
270| 
271|     const cfg = STAGES[Math.min(stage - 1, STAGES.length - 1)];
272| 
273|     spawnAccum += dt;
274|     if (spawnAccum >= cfg.spawnRate) {
275|       spawnAccum = 0;
276|       spawnFruit(cfg);
277|     }
278| 
279|     const wind = graceTimer > 0 ? 0 : windStrength;
280| 
281|     for (let i = fruits.length - 1; i >= 0; i--) {
282|       const f = fruits[i];
283|       f.y += f.vy * dt;
284|       f.wobble += dt * 2;
285|       f.x += Math.sin(f.wobble) * 8 * dt + wind * dt;
286|       f.x = Math.max(f.r, Math.min(W - f.r, f.x));
287| 
288|       // catch check
289|       const basketTop = H - 90;
290|       const basketBottom = H - 90 + basket.h * 0.6;
291|       if (f.y + f.r >= basketTop && f.y - f.r <= basketBottom) {
292|         if (Math.abs(f.x - basket.x) < basket.w / 2 + f.r * 0.4) {
293|           if (f.bad) {
294|             // empty basket: lose all progress this stage
295|             spawnBurst(f.x, f.y, COL_ACCENT);
296|             caughtGood = 0;
297|             flashMessage('Rotten! Basket emptied');
298|           } else {
299|             spawnBurst(f.x, f.y, COL_HIGHLIGHT);
300|             caughtGood++;
301|             score += 10;
302|             CARTRIDGE.send('score', { value: score });
303|             if (caughtGood >= goalCount) {
304|               fruits.splice(i, 1);
305|               onGoalMet();
306|               continue;
307|             }
308|           }
309|           fruits.splice(i, 1);
310|           continue;
311|         }
312|       }
313| 
314|       if (f.y - f.r > H) {
315|         fruits.splice(i, 1);
316|         if (!f.bad) {
317|           missed++;
318|           if (missed >= maxMissed) {
319|             onStageFailed();
320|             return;
321|           }
322|         }
323|       }
324|     }
325| 
326|     for (let i = particles.length - 1; i >= 0; i--) {
327|       const p = particles[i];
328|       p.life -= dt;
329|       p.x += p.vx * dt;
330|       p.y += p.vy * dt;
331|       p.vy += 300 * dt;
332|       if (p.life <= 0) particles.splice(i, 1);
333|     }
334|   }
335| 
336|   // ---- Drawing ----
337|   function drawShadowLayer(drawFn) {
338|     ctx.save();
339|     ctx.shadowColor = 'rgba(61,64,91,0.35)';
340|     ctx.shadowBlur = 6;
341|     ctx.shadowOffsetY = 3;
342|     drawFn();
343|     ctx.restore();
344|   }
345| 
346|   function drawBackground() {
347|     ctx.fillStyle = COL_BG;
348|     ctx.fillRect(0, 0, W, H);
349| 
350|     // paper-cut hills as layered rounded shapes
351|     drawShadowLayer(() => {
352|       ctx.fillStyle = COL_HIGHLIGHT;
353|       ctx.beginPath();
354|       ctx.moveTo(0, H - 60);
355|       for (let x = 0; x <= W; x += 40) {
356|         const y = H - 60 - Math.sin(x * 0.02) * 10;
357|         ctx.lineTo(jitter(x, 1.5), jitter(y, 1.5));
358|       }
359|       ctx.lineTo(W, H);
360|       ctx.lineTo(0, H);
361|       ctx.closePath();
362|       ctx.fill();
363|     });
364|   }
365| 
366|   function drawBasket() {
367|     const bx = basket.x - basket.w / 2;
368|     const by = H - 90;
369|     drawShadowLayer(() => {
370|       ctx.fillStyle = COL_LAYER;
371|       roundedRectPath(jitter(bx, 1.5), jitter(by, 1.5), basket.w, basket.h, 14);
372|       ctx.fill();
373|     });
374|     // basket weave lines
375|     ctx.strokeStyle = COL_ACCENT;
376|     ctx.lineWidth = 2;
377|     ctx.beginPath();
378|     for (let i = 1; i < 4; i++) {
379|       const lx = bx + (basket.w / 4) * i;
380|       ctx.moveTo(lx, by + 8);
381|       ctx.lineTo(lx, by + basket.h - 8);
382|     }
383|     ctx.stroke();
384|     // rim
385|     drawShadowLayer(() => {
386|       ctx.fillStyle = COL_ACCENT;
387|       roundedRectPath(bx - 4, by - 6, basket.w + 8, 10, 5);
388|       ctx.fill();
389|     });
390|   }
391| 
392|   function drawFruit(f) {
393|     const color = f.bad ? COL_ACCENT : COL_LAYER;
394|     drawShadowLayer(() => {
395|       ctx.fillStyle = color;
396|       ctx.beginPath();
397|       const jx = jitter(f.x, 1.2), jy = jitter(f.y, 1.2);
398|       ctx.arc(jx, jy, f.r, 0, Math.PI * 2);
399|       ctx.fill();
400|     });
401|     // leaf
402|     ctx.fillStyle = COL_HIGHLIGHT;
403|     ctx.beginPath();
404|     ctx.ellipse(f.x + f.r * 0.3, f.y - f.r * 0.9, f.r * 0.35, f.r * 0.18, -0.6, 0, Math.PI * 2);
405|     ctx.fill();
406|     // stem
407|     ctx.strokeStyle = COL_ACCENT;
408|     ctx.lineWidth = 2;
409|     ctx.beginPath();
410|     ctx.moveTo(f.x, f.y - f.r);
411|     ctx.lineTo(f.x, f.y - f.r * 1.3);
412|     ctx.stroke();
413|     if (f.bad) {
414|       // rotten spots
415|       ctx.fillStyle = COL_BG;
416|       for (let s = 0; s < 3; s++) {
417|         const ang = f.seed + s * 2;
418|         const sx = f.x + Math.cos(ang) * f.r * 0.4;
419|         const sy = f.y + Math.sin(ang) * f.r * 0.4;
420|         ctx.beginPath();
421|         ctx.arc(sx, sy, f.r * 0.15, 0, Math.PI * 2);
422|         ctx.fill();
423|       }
424|     }
425|   }
426| 
427|   function drawParticles() {
428|     for (const p of particles) {
429|       ctx.globalAlpha = Math.max(0, p.life / 0.6);
430|       ctx.fillStyle = p.color;
431|       ctx.beginPath();
432|       ctx.arc(p.x, p.y, 4, 0, Math.PI * 2);
433|       ctx.fill();
434|       ctx.globalAlpha = 1;
435|     }
436|   }
437| 
438|   function drawCardPlate(x, y, w, h, text, subtext) {
439|     drawShadowLayer(() => {
440|       ctx.fillStyle = COL_BG;
441|       roundedRectPath(x, y, w, h, 16);
442|       ctx.fill();
443|     });
444|     ctx.strokeStyle = COL_ACCENT;
445|     ctx.lineWidth = 2;
446|     roundedRectPath(x, y, w, h, 16);
447|     ctx.stroke();
448| 
449|     ctx.fillStyle = COL_ACCENT;
450|     ctx.textAlign = 'center';
451|     ctx.font = 'bold 28px sans-serif';
452|     ctx.fillText(text, x + w / 2, y + h / 2 - (subtext ? 8 : -6));
453|     if (subtext) {
454|       ctx.font = '18px sans-serif';
455|       ctx.fillText(subtext, x + w / 2, y + h / 2 + 24);
456|     }
457|   }
458| 
459|   function drawHUD() {
460|     // top card with stage info
461|     const w = Math.min(360, W - 40);
462|     const h = 64;
463|     const x = (W - w) / 2;
464|     const y = 12;
465|     drawShadowLayer(() => {
466|       ctx.fillStyle = COL_LAYER;
467|       roundedRectPath(x, y, w, h, 14);
468|       ctx.fill();
469|     });
470|     ctx.fillStyle = COL_BG;
471|     ctx.textAlign = 'left';
472|     ctx.font = 'bold 18px sans-serif';
473|     ctx.fillText('Stage ' + stage, x + 14, y + 26);
474|     ctx.font = '14px sans-serif';
475|     ctx.fillText('Apples ' + caughtGood + '/' + goalCount + '   Missed ' + missed + '/' + maxMissed, x + 14, y + 48);
476| 
477|     ctx.textAlign = 'right';
478|     ctx.font = 'bold 18px sans-serif';
479|     ctx.fillText('Score ' + score, x + w - 14, y + 26);
480| 
481|     if (messageFlashTimer > 0) {
482|       ctx.globalAlpha = Math.min(1, messageFlashTimer);
483|       const mw = Math.min(420, W - 40);
484|       const mh = 56;
485|       const mx = (W - mw) / 2;
486|       const my = y + h + 14;
487|       drawCardPlate(mx, my, mw, mh, messageFlashText, null);
488|       ctx.globalAlpha = 1;
489|     }
490| 
491|     if (graceTimer > 0) {
492|       ctx.fillStyle = COL_ACCENT;
493|       ctx.textAlign = 'center';
494|       ctx.font = '14px sans-serif';
495|       ctx.fillText('Get ready...', W / 2, H - 110);
496|     }
497|   }
498| 
499|   function render() {
500|     drawBackground();
501| 
502|     if (state === 'title') {
503|       drawCardPlate(W/2 - 180, H/2 - 90, 360, 180, 'Orchard Catch', 'Tap or drag to begin');
504|       ctx.fillStyle = COL_ACCENT;
505|       ctx.textAlign = 'center';
506|       ctx.font = '15px sans-serif';
507|       ctx.fillText('Catch good apples, dodge rotten ones!', W / 2, H / 2 + 120);
508|       return;
509|     }
510| 
511|     for (const f of fruits) drawFruit(f);
512|     drawBasket();
513|     drawParticles();
514|     drawHUD();
515| 
516|     if (state === 'stageclear') {
517|       drawCardPlate(W/2 - 170, H/2 - 60, 340, 120, 'Stage Clear!', 'Next stage incoming...');
518|     }
519| 
520|     if (state === 'gameover') {
521|       drawCardPlate(W/2 - 190, H/2 - 100, 380, 200, 'Game Over', 'Score ' + score);
522|       ctx.fillStyle = COL_ACCENT;
523|       ctx.textAlign = 'center';
524|       ctx.font = '16px sans-serif';
525|       ctx.fillText('Tap to retry', W / 2, H / 2 + 60);
526|     }
527| 
528|     if (state === 'win') {
529|       drawCardPlate(W/2 - 190, H/2 - 100, 380, 200, 'You Win!', 'Score ' + score);
530|       ctx.fillStyle = COL_ACCENT;
531|       ctx.textAlign = 'center';
532|       ctx.font = '16px sans-serif';
533|       ctx.fillText('Tap to play again', W / 2, H / 2 + 60);
534|     }
535|   }
536| 
537|   // ---- Host messages ----
538|   window.addEventListener('message', (event) => {
539|     const data = event.data;
540|     if (!data || data.source !== 'cartridge-host') return;
541|     if (data.type === 'pause') paused = true;
542|     if (data.type === 'resume') paused = false;
543|     if (data.type === 'reset') backToTitle();
544|   });
545| 
546|   // boot
547|   requestAnimationFrame((t) => {
548|     lastTime = t;
549|     render();
550|     CARTRIDGE.send('boot', { title: 'Orchard Catch', gameType: 'stage-clear', lang: 'en' });
551|     requestAnimationFrame(loop);
552|   });
553| })();
554| </script>
555| </body>
556| </html>
557|

